    rc.filter(x => !x.ok).forEach(x => checks.push([x.lvl === 3 ? 2 : x.lvl, T('Сверка мест: ', 'Packstückabgleich: ', 'Package check: ', 'Орындарды салыстыру: ') + x.id + ' — ' + T('отсканировано ', 'gescannt ', 'scanned ', 'сканерленді ') + x.n + T(' из ', ' von ', ' of ', ' / ') + x.exp + ' (SSCC) · ' + x.mark + LT('ops_load.trip_release_blocked_until_rescanned'), 'sscc']));
