    const SRC = { weighbridge: T('автомобильные весы', 'Fahrzeugwaage', 'weighbridge', 'автомобиль таразысы'), axle_scale: T('осевые весы', 'Achslastwaage', 'axle scale', 'ось таразысы'), manual: T('вручную', 'manuell', 'manual', 'қолмен') };
