    const latest = w ? `<div class="tinted-row ${w.ok ? 'green' : w.override ? 'yellow' : 'red'}" style="display:block" data-weigh-ok="${w.ok || w.override ? 1 : 0}">${esc(SRC[w.source])}${w.ticket ? ' · ' + esc(w.ticket) : ''} · ${esc(T('перед. ', 'VA ', 'front ', 'алд. '))}${w.front == null ? '—' : w.front} · ${esc(T('задн. ', 'HA ', 'rear ', 'арт. '))}${w.rear == null ? '—' : w.rear} · ${esc(T('полная ', 'gesamt ', 'gross ', 'толық '))}${w.gross} ${esc(KG)} · ${w.at} ${w.ok ? chip('green', T('в пределах ТС', 'innerhalb der Grenzen', 'within limits', 'шегінде')) : w.excess.map(x => chip(w.override ? 'yellow' : 'red', '+' + x.excess + ' ' + KG + ' ' + CODE[x.code] + ' (' + x.val + ' / ' + x.max + ')')).join(' ')}${w.override ? ' ' + chip('yellow', T('допущено с обоснованием', 'mit Begründung freigegeben', 'released with a reason', 'негіздемемен рұқсат етілді')) + ' <span class="sub">' + esc(w.reason) + '</span>' : ''}${!w.ok && !w.override ? `<div class="lw-ex">${esc(T('Выпуск рейса заблокирован: перегруз по взвешиванию', 'Tourfreigabe gesperrt: Überladung laut Verwiegung', 'Trip release blocked: overload by weighing', 'Рейс шығару бұғатталды: өлшеу бойынша артық жүк'))}</div>` : ''}</div>` : `<p class="note">${esc(T('Взвешивания нет — гейт проверяет расчёт загрузки.', 'Keine Verwiegung — das Gate prüft die Ladeberechnung.', 'No weighing — the gate checks the load calculation.', 'Өлшеу жоқ — қақпа тиеу есебін тексереді.'))}</p>`;
